(* [comment removed for export] *)
(* [comment removed for export] *)
Lemma eof_step (fx fx1 : FPState) R (pc : Z) R1 (pc1 : Z) M model s sm cr LK Aw (M1v : word -> option byte) :
  st_ok M model s sm cr LK Aw ->
  msteps RSEGS (L5SAR.st fx R pc (mrestrict (ahid Aw model) M)) (L5SAR.st fx1 R1 pc1 M1v) ->
  mem_grows (mrestrict (ahid Aw model) M) M1v ->
  (forall a, 0 <= a < 2 ^ 64 -> ~ (S - 184 <= a < S - 184 + 8) -> M1v (Z_to_bv 64 a) = mrestrict (ahid Aw model) M (Z_to_bv 64 a)) ->
  (forall M1 model1, st_ok M1 model1 s sm cr LK Aw ->
     (forall l, Z.of_nat (length l) <= PM.vs_size (PM.p_tb s) ->                                              (* [comment removed for export] *)
        L5.bytes_at RSEGS M (PM.vs_data tb (PM.p_tb s)) l -> L5.bytes_at RSEGS M1 (PM.vs_data tb (PM.p_tb s)) l) ->
     srealizes RSEGS SCFG (@PMSPA.cfg RSEGS fx1 R1 pc1 M1 model1) K) ->
